| لا يجوز (0,5ن) | عدم انتهاء العدة (0,5ن) |$sujet$,
  $sujet${"parties": [{"titre": "الأسئلة", "points": 20, "questions": [{"type": "libre", "numero": "1", "points": 1, "enonce": "حدد القضية المحورية للوضعية التقويمية.", "correction": "القضية الأساسية للوضعية: (يقبل كل جواب له علاقة بشمولية مفهوم الإحسان في سورة يوسف)."}, {"type": "libre", "numero": "2 أ", "points": 0.5, "enonce": "عرف في الاصطلاح الشرعي المفهومين الآتيين: أ- الإيمان", "correction": "- الإيمان: الاعتقاد القلبي الجازم بالله تعالى وملائكته وكتبه ورسله واليوم الآخر والقدر خيره وشره، وهو تصديق بالقلب، ونطق باللسان، وعمل بالجوارح (0,5ن)"}, {"type": "libre", "numero": "2 ب", "points": 0.5, "enonce": "عرف في الاصطلاح الشرعي المفهومين الآتيين: ب – العفة", "correction": "- العفة: حصول حالة للنفس ترتفع بها عن المحرمات والفواحش قولا وعملا (0,5ن)"}, {"type": "libre", "numero": "3 أ", "points": 1, "enonce": "من مظاهر إحسان يوسف عليه السلام تمثله قيم العفة والحياء والبذل. أ- بين أهمية التحلي بخلقي العفة والحياء في تحصين الفرد وحمايته من الفواحش.", "correction": "أ- أن يبين أهمية التحلي بخلق العفة والحياء في تحصين الفرد من الفواحش وحمايته من المجون وتشجيعه على التقوى والكف عن الشهوات، موظفا سمو هذا الخلق بيوسف عليه السلام وجعله في مأمن عن الرذيلة ناشرا بسلوكه وعفته الفضيلة مرتقيا أسمى المراتب والمناصب (1ن)"}, {"type": "libre", "numero": "3 ب", "points": 0.5, "enonce": "من مظاهر إحسان يوسف عليه السلام تمثله قيم العفة والحياء والبذل. ب - اذكر مظهرين من مظاهر بذل وعطاء عثمان بن عفان رضي الله عنه.", "correction": "ب – أن يذكر مثالين من بذل وعطاء عثمان بن عفان رضي الله عنه. - إنفاقه في الجهاد في سبيل الله ( تجهيزه جيش العسرة في غزوة تبوك ) (0,25ن) - إنفاقه في سقي الماء وشراؤه بئر رومة لصالح المسلمين (0,25ن)"}, {"type": "libre", "numero": "4", "points": 0.5, "enonce": "صبر يوسف عليه السلام ويقينه بنصر الله تعالى من تجليات إحسانه. بين أهمية قيمتي الصبر واليقين في حياة المؤمن انطلاقا مما درسته، مستثمرا ما رأيته في سورة يوسف.", "correction": "أن يبرز أهمية قيمتي الصبر واليقين في حياة المؤمن وذلك بتثبيت إيمانه على طاعة الله تعالى وتقبله للابتلاءات فيرضى بقضاء الله تعالى وقدره، ويعتز بدينه ويستعد لآخرته، اقتداء بالأنبياء في يقينهم الثابت وصبرهم الجميل."}, {"type": "libre", "numero": "5 أ", "points": 0.5, "enonce": "إحسان يوسف عليه السلام مع الخالق والخلق من مقتضيات إيمانه وعلمه. أ- استخرج من الوضعية أعلاه أثرين من آثار الإيمان بالغيب على السلوك.", "correction": "أ- أن يستخرج من الوضعية أثرين من آثار الإيمان بالغيب على السلوك: (التعفف عن المحرمات والفواحش – التحلي بالعفو والتسامح (0.25ن) – الالتزام بالحياء والبذل (0.25ن)"}, {"type": "libre", "numero": "5 ب", "points": 1, "enonce": "إحسان يوسف عليه السلام مع الخالق والخلق من مقتضيات إيمانه وعلمه. ب- بين أثر العلم الصحيح في ترسيخ الإيمان وتقويته.", "correction": "ب - أن يبين أن الانسان كلما ازداد علمه ازداد إيمانه، فكلما تبحر الانسان وتعمق في مجال المعارف والعلوم ازداد إحاطة وإدراكا بأسرار الكون التي تزيد إيمانه بالله رسوخا ويقينا بعظمة الخالق (1ن)"}, {"type": "libre", "numero": "6 أ", "points": 1, "enonce": "إعمال يوسف عليه السلام لمبادئ العفو والتسامح والتفاوض تجسيد عملي لقيمة الإحسان. أ- بين أهمية العفو والتسامح في نشر المحبة وتماسك المجتمع.", "correction": "أ- أن يبين أهمية العفو والتسامح في نشر المحبة والإخاء بين أفراد المجتمع وتحريرهم من المشاعر السلبية كالبغض والكراهية وتحل محلها المشاعر الايجابية التي تسهم في تحقيق وضمان استقرار المجتمع وتماسكه (1ن)"}, {"type": "libre", "numero": "6 ب", "points": 0.5, "enonce": "إعمال يوسف عليه السلام لمبادئ العفو والتسامح والتفاوض تجسيد عملي لقيمة الإحسان. ب- استحضر نموذجا لإعمال النبي ﷺ لمبدأ التفاوض مع القرشيين في صلح الحديبية.", "correction": "ب- تفاوض الرسول ﷺ مع سهيل بن عمرو القرشي في صلح الحديبية (0.5ن)"}, {"type": "libre", "numero": "7", "points": 1, "enonce": "من إحسان يوسف عليه السلام الوفاء بأمانة عمارة الأرض. أبرز أهمية مبدأ الاستخلاف في تحقيق عمارة الأرض.", "correction": "- أن يبين أن مبدأ الاستخلاف هو أساس عمارة الأرض، فالله عز وجل استخلف الانسان في هذه الأرض وأناط به مسؤولية تعمير الأرض على أساس الإصلاح والعدل والإحسان...بما ينفع الخلق ويرضى الخالق."}, {"type": "libre", "numero": "8 أ", "points": 1.5, "enonce": "يوسف عليه السلام قلب ينبض بالإحسان. استحضر من سورة يوسف الآيات المناسبة للمعاني الآتية: أ- امتناع يوسف عليه السلام عن الفاحشة رغم مراودة امرأة العزيز له.", "correction": "أن يستدل من سورة يوسف بالآيات المناسبة للمعاني المحددة: أ- قال تعالى: ﴿وَرَٰوَدَتْهُ اُ۬لتِے هُوَ فِے بَيْتِهَا عَن نَّفْسِهِۦ وَغَلَّقَتِ اِ۬لْأَبْوَٰبَ وَقَالَتْ هِيتَ لَكَ قَالَ مَعَاذَ اَ۬للَّهِ إِنَّهُۥ رَبِّيَ أَحْسَنَ مَثْوَايَ إِنَّهُۥ لَا يُفْلِحُ اُ۬لظَّٰلِمُونَ ۝٢٣ وَلَقَدْ هَمَّتْ بِهِۦ وَهَمَّ بِهَا لَوْلَا أَن رَّءِا بُرْهَٰنَ رَبِّهِۦ كَذَٰلِكَ لِنَصْرِفَ عَنْهُ اُ۬لسُّوٓءَ وَالْفَحْشَآءَ إِنَّهُۥ مِنْ عِبَادِنَا اَ۬لْمُخْلَصِينَ﴾ (1.5ن)"}, {"type": "libre", "numero": "8 ب", "points": 1.5, "enonce": "يوسف عليه السلام قلب ينبض بالإحسان. استحضر من سورة يوسف الآيات المناسبة للمعاني الآتية: ب- إرشاد يوسف عليه السلام صاحبيه في السجن إلى التوحيد ودعوتهما إلى نبذ الشرك والتقليد.", "correction": "ب – قال تعالى: ﴿يَٰصَٰحِبَيِ اِ۬لسِّجْنِ ءَآرْبَابٌ مُّتَفَرِّقُونَ خَيْرٌ اَمِ اِ۬للَّهُ اُ۬لْوَٰحِدُ اُ۬لْقَهَّارُ مَا تَعْبُدُونَ مِن دُونِهِۦ إِلَّآ أَسْمَآءً سَمَّيْتُمُوهَآ أَنتُمْ وَءَابَآؤُكُم مَّآ أَنزَلَ اَ۬للَّهُ بِهَا مِن سُلْطَٰنٍ اِنِ اِ۬لْحُكْمُ إِلَّا لِلَّهِ أَمَرَ أَلَّا تَعْبُدُوٓاْ إِلَّآ إِيَّاهُ ذَٰلِكَ اَ۬لدِّينُ اُ۬لْقَيِّمُ وَلَٰكِنَّ أَكْثَرَ اَ۬لنَّاسِ لَا يَعْلَمُونَ﴾ (1.5ن)"}, {"type": "libre", "numero": "9", "points": 2, "enonce": "مما يتعارض وقيمة الإحسان ميل بعض الشباب إلى ارتكاب الفواحش وربط علاقات غير شرعية للتملص من تبعات الزواج والتهرب من مسؤوليته. حدد موقفك من هذا التصرف مستثمرا ما درسته.", "correction": "أن يبدي عدم اتفاقه مع هذا التصرف معللا موقفه بما يناسب من الأدلة العقلية أو الشرعية على المكانة العظيمة للزواج في الإسلام كونه السبيل الوحيد لحفظ الدين والنفس والعرض وضامن الاستقرار النفسي والاجتماعي للإنسان."}, {"type": "libre", "numero": "10 أ", "points": 1, "enonce": "استثمر السند المصاحب للوضعية التقويمية وما درسته في الإجابة عن الآتي: أ- بين موقفك من الاتفاق الذي حصل بين المسلمين والمشركين في صلح الحديبية.", "correction": "أ- أن يعبر عن موقف إيجابي من الاتفاق الحاصل بين المسلمين والمشركين في صلح الحديبية، لكون هذا الاتفاق كان بمثابة حقن لدماء المسلمين، وتجنيبا لهم من الدخول في حرب قد لا يكونون مستعدين لها، إضافة إلى أنه حقق الحد الأدنى من مصلحة المسلمين من خلال ما تضمنه من بنود (1ن)"}, {"type": "libre", "numero": "10 ب", "points": 1, "enonce": "استثمر السند المصاحب للوضعية التقويمية وما درسته في الإجابة عن الآتي: ب- وضح كيف كان صلح الحديبية سببا في فتح مكة.", "correction": "ب – أن يبين أن سبب فتح مكة هو نقض القرشيين للبنود التي تم الاتفاق عليها مع المسلمين في صلح الحديبية ومنها وضع الحرب لمدة عشر سنوات (1ن)"}, {"type": "tableau", "numero": "11-1", "points": 1, "enonce": "اقرأ المقاطع القرآنية أدناه من سورة يوسف ثم املأ الجدول بما يناسب: المقطع القرآني: ﴿وَاللَّهُ اُ۬لْمُسْتَعَانُ عَلَىٰ مَا تَصِفُونَ﴾", "champs": [{"libelle": "القيمة", "reponse": "اليقين (0,5ن)"}, {"libelle": "فوائدها وثمراتها", "reponse": "ترسيخ الثقة في نصر الله وتأييده والمضي على الحق بعزم وثبات (0,5ن)"}]}, {"type": "tableau", "numero": "11-2", "points": 1, "enonce": "اقرأ المقاطع القرآنية أدناه من سورة يوسف ثم املأ الجدول بما يناسب: المقطع القرآني: ﴿وَكَذَٰلِكَ نَجْزِے اِ۬لْمُحْسِنِينَ﴾", "champs": [{"libelle": "القيمة", "reponse": "الاحسان (0,5ن)"}, {"libelle": "فوائدها وثمراتها", "reponse": "نيل محبة الله تعالى - الإخلاص في تحمل المسؤولية -إتقان العمل (0,5ن)"}]}, {"type": "tableau", "numero": "11-3", "points": 1, "enonce": "اقرأ المقاطع القرآنية أدناه من سورة يوسف ثم املأ الجدول بما يناسب: المقطع القرآني: ﴿أَنِّے لَمَ اَخُنْهُ بِالْغَيْبِ وَأَنَّ اَ۬للَّهَ لَا يَهْدِے كَيْدَ اَ۬لْخَآئِنِينَ﴾", "champs": [{"libelle": "القيمة", "reponse": "الوفاء بالأمانة (0,5ن)"}, {"libelle": "فوائدها وثمراتها", "reponse": "نشر الثقة والمحبة بين أفراد المجتمع (0,5ن)"}]}, {"type": "tableau", "numero": "12-1", "points": 1, "enonce": "تأمل التصرفات أدناه ثم املأ الجدول بما يناسب: التصرف: اتفق شاب وشابة على الزواج طيلة مدة دراستهما ببلاد المهجر", "champs": [{"libelle": "الحكم الشرعي (جائز / غير جائز)", "reponse": "لا يجوز (0,5ن)"}, {"libelle": "التعليل", "reponse": "الزواج يكون على وجه الدوام (0,5ن)"}]}, {"type": "tableau", "numero": "12-2", "points": 1, "enonce": "تأمل التصرفات أدناه ثم املأ الجدول بما يناسب: التصرف: تزوج رجل امرأة مطلقة وهي ما تزال حاملا من زوجها الأول", "champs": [{"libelle": "الحكم الشرعي (جائز / غير جائز)", "reponse": "لا يجوز (0,5ن)"}, {"libelle": "التعليل", "reponse": "عدم انتهاء العدة (0,5ن)"}]}], "texte": "### الوضعية التقويمية:\n\nيختزل بعض الناس مفهوم الإحسان في دائرة التصدق وبذل القليل من المال على الفقراء والمحتاجين، إلا أن المتدبر لآيات كتاب الله تعالى وخاصة سورة يوسف يجد أن هذا المفهوم يتجاوز هذه النظرة الضيقة ليشمل معاني واسعة ودلالات عميقة صاحبت سيرة يوسف عليه السلام في مختلف مراحله العمرية بدءا بفترة الشباب وما لقيه من إغواء وإغراء امرأة العزيز، وما كابده من ظلم وكيد بدخوله السجن، وصولا إلى تمكين الله له بتبوئه لخزائن مصر وتحمله للأمانة والمسؤولية بكفاءة واستحقاق، وانتهاء بلقاء إخوته وإكرام وفادتهم وعفوه عليهم واستقدام أهله إلى مصر.\n\nإن احسان يوسف عليه السلام مع الخالق والخلق يجعل منه قدوة للشباب في التعفف عن المحرمات والفواحش الظاهرة والباطنة، ومدرسة لهم في الصبر واليقين بنصر الله تعالى، ومثالا لهم في الحياء والبذل، ونبراسا يحتذى في العلم والإيمان، مما يكفل اعداد جيل يتخذ من الايمان الحق منطلقا لبناء أسر تسودها قيم المودة والرحمة بين الزوجين، ويحيا أفرادها في ظل قيم التشاور والتفاوض، ويتحلون بقيمة العفو والتسامح، ويقدرون حجم المسؤولية الملقاة على عاتقهم في رعاية الأطفال وصون حقوقهم وتأهيلهم للإسهام في عمارة الأرض وإصلاحها بما يحقق الخير للإنسانية جمعاء اقتداء بهدي النبي ﷺ وأخلاقه في تدبير شؤون البلاد والعباد.\n\n### السند:\n\nعَنِ الْبَرَاءِ بْنِ عَازِبٍ قَال: كَتَبَ عَلِيُّ بْنُ أَبِي طَالِبٍ الصُّلْحَ بَيْنَ النَّبِيِّ - ﷺ - وَبَيْنَ الْمُشْرِكِينَ يَوْمَ الْحُدَيْبِيَةِ، فَكَتَبَ: هَذَا مَا كَاتَبَ عَلَيهِ مُحَمَّدٌ رَسُولُ اللهِ، فَقَالُوا: لا تَكْتُبْ رَسُولُ اللهِ فَلَوْ نَعْلَمُ أَنَّكَ رَسُولُ اللهِ لَمْ نُقَاتِلْكَ، فَقَال النبيُّ - ﷺ - لِعَلِي: (امْحُهُ). قَال: مَا أَنَا بِالَّذِي أَمْحُهُ، قَال: فَمَحَاهُ النَّبِيُّ - ﷺ - بِيَدِهِ، قَال: وَكَانَ فِيمَا اشْتَرَطُوا عَلَيهِ أَنْ يَدْخُلُوا مَكَّةَ فيقِيمُوا بِهَا ثَلاثًا، وَلا يَدْخُلَهَا بِسِلاحٍ إِلا جُلُبَّانَ السّلاحِ. قَال شُعْبَةُ: قُلْتُ لأَبِي إِسْحَقَ: وَمَا جُلُبَّانُ السّلاحِ؛ قَال: الْقِرَابُ وَمَا فِيهِ.\n\n*الجمع بين الصحيحين . أبو محمد عبد الحق بن عبد الرحمن الإشبيلي (3/ 62).*", "consigne": "اقرأ الوضعية التقويمية والسند المصاحب، ثم أجب عن الأسئلة المرافقة:"}]}$sujet$::jsonb
)
